-- Import official SAHA USSA hockey records for CUT, 2024 and 2025.
select (select id from public.sports where slug='hockey'),v.name,v.season,v.start_date::date,v.end_date::date,v.venue,v.description,'published'
from (values
('USSA Men B-Section','2024','2024-07-01','2024-07-05','Johannesburg','2024 SAHA USSA Men B-Section. CUT finished 5th.'),
('USSA Women C-Section','2024','2024-07-01','2024-07-05','Johannesburg','2024 SAHA USSA Women C-Section. CUT finished 1st.'),
('USSA Men B-Section','2025','2025-06-30','2025-07-04','Stellenbosch','2025 SAHA USSA Men B-Section. CUT finished 4th.'),
('USSA Women B-Section','2025','2025-06-30','2025-07-04','Stellenbosch','2025 SAHA USSA Women B-Section. CUT finished 4th.')
) v(name,season,start_date,end_date,venue,description)
where not exists(select 1 from public.competitions c where c.sport_id=(select id from public.sports where slug='hockey') and c.name=v.name and c.season=v.season);

on conflict (competition_id,source_match_id) do update set starts_at=excluded.starts_at,home_team=excluded.home_team,away_team=excluded.away_team,home_score=excluded.home_score,away_score=excluded.away_score,match_status='official',match_round=excluded.match_round,group_name=excluded.group_name,venue=excluded.venue,source_url=excluded.source_url,source_checked_at=now();

on conflict (competition_id,team_name,group_name) do update set position=excluded.position,played=excluded.played,won=excluded.won,drawn=excluded.drawn,lost=excluded.lost,scored=excluded.scored,conceded=excluded.conceded,points_difference=excluded.points_difference,points=excluded.points,source_url=excluded.source_url,source_checked_at=now();

on conflict (competition_id,player_name,team_name) do update set squad_number=excluded.squad_number,field_goals=excluded.field_goals,penalty_corner_goals=excluded.penalty_corner_goals,penalty_stroke_goals=excluded.penalty_stroke_goals,total_goals=excluded.total_goals,source_url=excluded.source_url,source_checked_at=now();

on conflict (competition_id,team_name) do update set field_goals=excluded.field_goals,penalty_corner_goals=excluded.penalty_corner_goals,penalty_stroke_goals=excluded.penalty_stroke_goals,total_goals=excluded.total_goals,source_url=excluded.source_url,source_checked_at=now();
